parameters.jsCode:
// LLM 응답 (JSON 문자열) 파싱
const raw = String($input.first().json.choices?.[0]?.message?.content ?? '').trim().replace(/^```(json)?\s*|```$/g, '');
let data;
try {
  data = JSON.parse(raw);
} catch (error) {
  return [{ json: { error: 'LLM 응답이 올바른 JSON 형식이 아닙니다.', raw } }];
}

const settings = $('Settings').first().json;
const title = settings.title || '10월 16일 주간 회의';
const summary = String(data.summary ?? '').trim() || '회의 요약이 없습니다.';

// 할 일 목록 파싱 및 우선순위/null 처리
const rawActions = Array.isArray(data.actions) ? data.actions : [];
const actions = rawActions
  .filter(item => item && String(item.task ?? '').trim())
  .map(item => {
    const task = String(item.task).trim();

    // 담당자: 없거나 미정/null이면 null 처리
    let owner = item.owner ? String(item.owner).trim() : null;
    if (!owner || owner === '미정' || owner === 'null' || owner === '없음') {
      owner = null;
    }

    // 기한: 없거나 미정/null이면 null 처리
    let due = item.due ? String(item.due).trim() : null;
    if (!due || due === '미정' || due === 'null' || due === '없음') {
      due = null;
    }

    // 우선순위 판별: 오늘까지 -> 높음, 이번주까지 / 기타 -> 보통
    let priority = '보통';
    if (due && ['오늘', '금일', '당일', '긴급'].some(w => due.includes(w))) {
      priority = '높음';
    }

    return {
      task,
      owner,
      due,
      priority
    };
  });

const count = actions.length;
const route = count > 0 ? '할 일 정리' : '할 일 없음';

// 공유용 정리문 (report_text)
const actionLines = actions.map((a, i) => {
  const ownerStr = a.owner ? a.owner : '담당자 미정';
  const dueStr = a.due ? a.due : '기한 미정';
  return `${i + 1}. [${a.priority}] ${a.task} - ${ownerStr} (${dueStr})`;
});

const report_text = count > 0
  ? `${title}\n${summary}\n\n[할 일 목록]\n${actionLines.join('\n')}`
  : `${title}\n${summary}\n\n(등록된 할 일이 없습니다.)`;

return [{
  json: {
    title,
    route,
    count,
    summary,
    actions,
    report_text
  }
}];
